INSERT INTO `position` (`position_name`, `position_details`) VALUES ('chef', 'Responsible for the pastry shop in a foodservice establishment. Ensures that the products produced in the pastry shop meet the quality standards in conjunction with the executive chef.');
INSERT INTO `position` (`position_name`, `position_details`) VALUES ('HRM', 'Recruits and hires qualified employees, creates in-house job-training programs, and assists employees with their career needs.');
INSERT INTO `position` (`position_name`, `position_details`) VALUES ('Kitchen manager', 'Supervises and coordinates activities concerning all back-of-the-house operations and personnel, including food preparation, kitchen and storeroom areas.');
INSERT INTO `position` (`position_name`, `position_details`) VALUES ('Counter server', 'Responsible for providing quick and efficient service to customers. Greets customers, takes their food and beverage orders, rings orders into register, and prepares and serves hot and cold drinks.');
INSERT INTO `position` (`position_name`, `position_details`) VALUES ('Cashier', 'Like the drive-thru operator, cashiers must accurately record a customer’s order and handle cash to process the transaction. Cashiers must be able to listen when customers have problems or');
INSERT INTO `position` (`position_name`, `position_details`) VALUES ('Waiter', 'Most waiters and waitresses, also called servers, work in full-service restaurants. They greet customers, take food orders, bring food and drinks to the tables and take payment and make change.');
INSERT INTO `position` (`position_name`, `position_details`) VALUES ('Accounts', 'Play a key role in every restaurant. ');
