CREATE TABLE `tbl_bookParking` (
  `bookParking_id` int(11) NOT NULL AUTO_INCREMENT,
  `bookedid` int(11) DEFAULT NULL,
  `parkingSetting_id` int(11) DEFAULT NULL,
  `zone_id` int(11) DEFAULT NULL,
