UPDATE tbl_roomnofloorassign JOIN booked_info ON FIND_IN_SET(tbl_roomnofloorassign.roomno,booked_info.room_no)<>0 SET `tbl_roomnofloorassign`.`status` = 1
WHERE `booked_info`.`checkoutdate` < '2025-02-13 14:35:13'
AND `tbl_roomnofloorassign`.`status` <> 1;
UPDATE tbl_roomnofloorassign JOIN booked_info ON FIND_IN_SET(tbl_roomnofloorassign.roomno,booked_info.room_no)<>0 SET `tbl_roomnofloorassign`.`status` = 2
WHERE `booked_info`.`checkindate` < '2025-02-13 14:35:13'
AND `booked_info`.`checkoutdate` > '2025-02-13 14:35:13'
AND `tbl_roomnofloorassign`.`status` <> 2
AND `booked_info`.`bookingstatus` IN(0, 4);
